// Área do Expert, Fase 2, Task 3 — createTrackedLinkForRecipient: one tracked
// link for one lead, generated by hand (the expert sends it over their own
// WhatsApp). Shortened on Short.io when the house has it enabled with a
// resolved domain, else the first-party redirect; the click is tracked either
// way through the link_dispatches row.
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { createFakeDb } from "./sms-bulk.test-support";

const fake = vi.hoisted(() => ({ db: null as unknown as ReturnType<typeof createFakeDb> }));

vi.mock("@/integrations/supabase/client.server", async () => {
  const { createFakeDb } = await import("./sms-bulk.test-support");
  fake.db = createFakeDb();
  return { supabaseAdmin: fake.db.client };
});
vi.mock("./tenant-access.server", () => ({
  assertTenantNotDemoForSend: vi.fn(async () => undefined),
  demoSendBlockedReason: vi.fn(async () => null),
  listDemoTenantIds: vi.fn(async () => []),
}));

import { verifyClickTokenSignature } from "./click-tracking.server";
import {
  __resetShortenerDomainCacheForTests,
  createTrackedLinkForRecipient,
  DestinationNotAllowedError,
  ShortenerUnavailableError,
} from "./shortio.server";

const TENANT = "00000000-0000-4000-8000-0000000000a1";
const PLAYER = "00000000-0000-4000-8000-0000000000b1";
const EXPERT = "00000000-0000-4000-8000-0000000000e1";
const PASTED = "https://casa.bet/bonus?promo=VOLTA50";

const INPUT = {
  tenantId: TENANT,
  originalUrl: PASTED,
  channel: "whatsapp" as const,
  sourceType: "expert" as const,
  sourceId: EXPERT,
  recipientPlayerId: PLAYER,
  deliveryKey: "expert_links:11111111-1111-4111-8111-111111111111",
};

const shortioCalls: Array<Record<string, unknown>> = [];
let shortioStatus = 200;

function seedSettings(over: Record<string, unknown> = {}) {
  fake.db.rows("shortio_settings").push({
    tenant_id: TENANT,
    enabled: true,
    fallback_mode: "block",
    default_ttl_days: null,
    allowed_destination_hosts: [],
    enabled_channels: ["sms", "email"],
    ...over,
  });
}

beforeEach(() => {
  fake.db.reset();
  __resetShortenerDomainCacheForTests();
  shortioCalls.length = 0;
  shortioStatus = 200;
  vi.stubEnv("SHORTIO_DOMAIN", "crm.short");
  vi.stubEnv("SHORTIO_API_KEY", "shortio-test-key");
  vi.stubEnv("SHORTIO_ENABLED", "");
  vi.stubEnv("CLICK_TRACKING_SECRET", "x".repeat(40));
  vi.stubEnv("PUBLIC_APP_URL", "https://app.example");
  vi.stubGlobal(
    "fetch",
    vi.fn(async (url: string | URL, init?: RequestInit) => {
      const href = String(url);
      const body = JSON.parse(String(init?.body ?? "{}")) as Record<string, unknown>;
      shortioCalls.push({ href, ...body });
      if (href !== "https://api.short.io/links") throw new Error(`unexpected fetch ${href}`);
      if (shortioStatus !== 200) return Response.json({ error: "nope" }, { status: shortioStatus });
      return Response.json({
        id: `lnk_${shortioCalls.length}`,
        shortURL: `https://${String(body.domain)}/s${shortioCalls.length}`,
      });
    }),
  );
});

afterEach(() => {
  vi.unstubAllEnvs();
  vi.unstubAllGlobals();
});

describe("createTrackedLinkForRecipient", () => {
  it("shortens when the house has Short.io enabled", async () => {
    seedSettings();
    const result = await createTrackedLinkForRecipient(INPUT);

    expect(result.shortened).toBe(true);
    expect(result.sentUrl).toBe("https://crm.short/s1");
    expect(shortioCalls).toHaveLength(1);
    // Short.io shortens our signed first-party redirect, never the bonus URL.
    const shortened = new URL(String(shortioCalls[0].originalURL));
    expect(shortened.origin).toBe("https://app.example");
    expect(shortened.pathname).toBe(`/api/public/click/${result.trackingToken}`);
    await expect(
      verifyClickTokenSignature(result.trackingToken, shortened.searchParams.get("s")),
    ).resolves.toBe(true);

    const [dispatch] = fake.db.rows("link_dispatches");
    expect(dispatch).toMatchObject({
      id: result.dispatchId,
      tracking_token: result.trackingToken,
      sent_url: "https://crm.short/s1",
      // The click route 302s to original_url: it must be the pasted URL.
      original_url: PASTED,
    });
  });

  it("returns the first-party tracked URL when Short.io is disabled", async () => {
    seedSettings({ enabled: false });
    const result = await createTrackedLinkForRecipient(INPUT);

    expect(result.shortened).toBe(false);
    expect(shortioCalls).toHaveLength(0);
    const url = new URL(result.sentUrl);
    expect(url.origin).toBe("https://app.example");
    expect(url.pathname).toBe(`/api/public/click/${result.trackingToken}`);

    const [dispatch] = fake.db.rows("link_dispatches");
    expect(dispatch).toMatchObject({ sent_url: result.sentUrl, original_url: PASTED });
    // link_dispatches.tracked_link_id is NOT NULL: a first-party row backs it,
    // kept out of the Short.io stats sync (status <> 'active').
    const [tracked] = fake.db.rows("tracked_links");
    expect(dispatch.tracked_link_id).toBe(tracked.id);
    expect(tracked).toMatchObject({ short_url: result.sentUrl, status: "failed" });
    expect(String(tracked.shortio_link_id)).toMatch(/^first-party:/);
  });

  it("ignores enabled_channels for manual whatsapp generation", async () => {
    seedSettings({ enabled_channels: ["sms"] });
    const result = await createTrackedLinkForRecipient(INPUT);

    expect(result.shortened).toBe(true);
    expect(shortioCalls).toHaveLength(1);
    expect(fake.db.rows("link_dispatches")).toHaveLength(1);
  });

  it("Short.io failure throws ShortenerUnavailableError and persists no dispatch", async () => {
    seedSettings();
    shortioStatus = 400;
    const error = vi.spyOn(console, "error").mockImplementation(() => undefined);

    await expect(createTrackedLinkForRecipient(INPUT)).rejects.toBeInstanceOf(
      ShortenerUnavailableError,
    );
    expect(fake.db.rows("link_dispatches")).toHaveLength(0);
    expect(fake.db.rows("tracked_links")).toHaveLength(0);
    error.mockRestore();
  });

  it("marks the dispatch as sent with source_type expert and recipient_player_id", async () => {
    seedSettings();
    const result = await createTrackedLinkForRecipient(INPUT);

    const [dispatch] = fake.db.rows("link_dispatches");
    expect(dispatch).toMatchObject({
      id: result.dispatchId,
      tenant_id: TENANT,
      channel: "whatsapp",
      source_type: "expert",
      source_id: EXPERT,
      recipient_player_id: PLAYER,
      message_log_type: "expert_links",
      idempotency_key: `${INPUT.deliveryKey}:0`,
      send_status: "sent",
    });
    expect(typeof dispatch.sent_at).toBe("string");
  });
  it("two generations for the same lead and URL create distinct dispatches", async () => {
    seedSettings();
    const first = await createTrackedLinkForRecipient(INPUT);
    const second = await createTrackedLinkForRecipient({
      ...INPUT,
      deliveryKey: "expert_links:22222222-2222-4222-8222-222222222222",
    });

    const dispatches = fake.db.rows("link_dispatches");
    expect(dispatches).toHaveLength(2);
    expect(first.dispatchId).not.toBe(second.dispatchId);
    expect(first.trackingToken).not.toBe(second.trackingToken);
    expect(dispatches[0].idempotency_key).not.toBe(dispatches[1].idempotency_key);
    expect(first.sentUrl).not.toBe(second.sentUrl);
  });

  it("refuses a protected destination before any Short.io call or write", async () => {
    seedSettings();
    await expect(
      createTrackedLinkForRecipient({ ...INPUT, originalUrl: "https://casa.bet/login?token=abc" }),
    ).rejects.toBeInstanceOf(DestinationNotAllowedError);
    expect(shortioCalls).toHaveLength(0);
    expect(fake.db.rows("link_dispatches")).toHaveLength(0);
    expect(fake.db.rows("tracked_links")).toHaveLength(0);
  });

  it("refuses a host outside the house allowlist", async () => {
    seedSettings({ allowed_destination_hosts: ["casa.bet"] });
    await expect(
      createTrackedLinkForRecipient({ ...INPUT, originalUrl: "https://outra.bet/bonus" }),
    ).rejects.toBeInstanceOf(DestinationNotAllowedError);
    expect(shortioCalls).toHaveLength(0);
    expect(fake.db.rows("link_dispatches")).toHaveLength(0);
    expect(fake.db.rows("tracked_links")).toHaveLength(0);
  });

  it("accepts a host inside the house allowlist (subdomains included)", async () => {
    seedSettings({ allowed_destination_hosts: ["CASA.bet"] });
    const result = await createTrackedLinkForRecipient({
      ...INPUT,
      originalUrl: "https://app.casa.bet/bonus",
    });
    expect(result.shortened).toBe(true);
    expect(fake.db.rows("link_dispatches")).toHaveLength(1);
  });

  it("accepts any http(s) host when the allowlist is empty", async () => {
    seedSettings({ enabled: false, allowed_destination_hosts: [] });
    const result = await createTrackedLinkForRecipient({
      ...INPUT,
      originalUrl: "http://qualquer.example/oferta",
    });
    expect(result.shortened).toBe(false);
    expect(fake.db.rows("link_dispatches")[0].original_url).toBe("http://qualquer.example/oferta");
  });

  it("a dispatch write failure throws ShortenerUnavailableError and leaves no dispatch", async () => {
    seedSettings();
    fake.db.failNext("link_dispatches", "upsert", "db down");
    const error = vi.spyOn(console, "error").mockImplementation(() => undefined);

    await expect(createTrackedLinkForRecipient(INPUT)).rejects.toBeInstanceOf(
      ShortenerUnavailableError,
    );
    expect(fake.db.rows("link_dispatches")).toHaveLength(0);
    error.mockRestore();
  });

  it("a shortener domain lookup failure throws ShortenerUnavailableError", async () => {
    seedSettings();
    fake.db.failNext("tenant_domains", "select", "db down");
    const error = vi.spyOn(console, "error").mockImplementation(() => undefined);

    await expect(createTrackedLinkForRecipient(INPUT)).rejects.toBeInstanceOf(
      ShortenerUnavailableError,
    );
    expect(shortioCalls).toHaveLength(0);
    expect(fake.db.rows("link_dispatches")).toHaveLength(0);
    expect(fake.db.rows("tracked_links")).toHaveLength(0);
    error.mockRestore();
  });
});
